/**
 * Unique and limited structures of the overworld.
 *
 * Kame House, Goku's house, the Cell Games arena, West City, Babidi's spaceship and the generic cities used to be
 * generated by structure sets (worldgen/structure_sets), so they repeated every ~500 blocks. Bedrock has no
 * "N per world" rule for structure sets, so they are placed by this script instead (like the Lookout and Korin
 * Tower, which the core places once at fixed coordinates):
 *   - one spot per structure is planned near the world spawn, in the right biome. The search runs on the world
 *     seed (Dimension.calculateClosestBiomeFromSeed), so it works for chunks that do not exist yet;
 *   - the structure is placed with StructureManager.placeJigsawStructure (same pieces and start height as the old
 *     structure sets) only when a player comes close, so no far chunk is forced to generate;
 *   - the plan and what was placed are saved in the world (PLAN_PROP): nothing is planned or placed twice.
 * Worlds created before this change keep the copies they already generated; only new chunks stop getting more.
 *
 * Operators: /scriptevent dbe:structures -> lists every planned spot and whether it was already placed.
 */
import * as mc from "@minecraft/server";

const { world, system } = mc;

const OVERWORLD = "minecraft:overworld";
const MIN_Y = -64;
const PLAN_PROP = "dbe:world_structures"; // JSON { v, spots: { key: { x, z, placed, tries, fallback } } }
const PLAN_VERSION = 1;
const SCAN_TICKS = 40;
const PLACE_DISTANCE = 96; // a player this close (horizontally) to a planned spot triggers the placement
const MIN_SEPARATION = 400; // minimum distance between two planned structures
const MAX_TRIES = 5; // placement attempts before a spot is given up (reported by the operator command)

const WARM_OCEANS = ["minecraft:warm_ocean", "minecraft:lukewarm_ocean", "minecraft:ocean", "minecraft:deep_lukewarm_ocean", "minecraft:deep_ocean"];
const WEST_CITY_BIOMES = ["minecraft:plains", "dbe:dirtstone_plains", "dbe:west_forest"];
const CITY_BIOMES = ["minecraft:plains", "minecraft:sunflower_plains", "minecraft:forest", "minecraft:birch_forest", "minecraft:savanna", "minecraft:taiga", "dbe:dirtstone_plains", "dbe:west_forest"];

/**
 * key: id of the spot in the saved plan. structure: jigsaw structure id (worldgen/structures). biomes: allowed biomes,
 * taken from the old structure biome filters. angle/dist: where the biome search starts, relative to the world spawn,
 * so the structures end up spread around it. area: half size of the ticking area kept loaded while placing.
 */
const SPECS = [
  { key: "kame_house", structure: "dbe:master_roshi_house", biomes: WARM_OCEANS, angle: 90, dist: 600, area: 32 },
  { key: "goku_house", structure: "dbe:goku_house", biomes: ["dbe:dirtstone"], angle: 0, dist: 600, area: 32 },
  { key: "cell_arena", structure: "dbe:cell_arena", biomes: ["dbe:dirtstone_plains"], angle: 180, dist: 700, area: 48 },
  { key: "babidi_spaceship", structure: "dbe:babidi_spaceship", biomes: ["minecraft:desert"], angle: 270, dist: 900, area: 48 },
  ...[45, 165, 285].map((angle, i) => ({ key: "west_city_" + (i + 1), structure: "dbe:west_city", biomes: WEST_CITY_BIOMES, angle, dist: 1200, area: 64 })),
  ...[20, 92, 164, 236, 308].map((angle, i) => ({ key: "city_" + (i + 1), structure: "dbe:city", biomes: CITY_BIOMES, angle, dist: 2000, area: 64 })),
];

const waitTicks = (n) => new Promise((resolve) => system.runTimeout(resolve, n));

function loadPlan() {
  try {
    const raw = world.getDynamicProperty(PLAN_PROP);
    const plan = typeof raw === "string" ? JSON.parse(raw) : null;
    if (plan && plan.v === PLAN_VERSION && plan.spots) return plan;
  } catch (e) {
    console.warn("[Structures] saved plan unreadable, planning again: " + e);
  }
  return { v: PLAN_VERSION, spots: {} };
}

function savePlan(plan) {
  world.setDynamicProperty(PLAN_PROP, JSON.stringify(plan));
}

/** Closest allowed biome from the search origin, far enough from the spots already planned. */
function planSpot(dim, spec, taken) {
  let spawn;
  try {
    spawn = world.getDefaultSpawnLocation();
  } catch (e) {
    spawn = { x: 0, z: 0 };
  }
  const a = (spec.angle * Math.PI) / 180;
  for (let attempt = 0; attempt < 3; attempt++) {
    const d = spec.dist * (1 + attempt * 0.75); // nothing usable: search again further out
    const from = { x: Math.round(spawn.x + Math.cos(a) * d), y: 0, z: Math.round(spawn.z + Math.sin(a) * d) };
    let best;
    for (const biome of spec.biomes) {
      let p;
      try {
        p = dim.calculateClosestBiomeFromSeed(from, biome);
      } catch (e) {
        p = undefined; // biome unknown in this world type (e.g. flat world)
      }
      if (!p) continue;
      if (taken.some((t) => Math.hypot(t.x - p.x, t.z - p.z) < MIN_SEPARATION)) continue;
      const dd = Math.hypot(p.x - from.x, p.z - from.z);
      if (!best || dd < best.d) best = { x: Math.round(p.x), z: Math.round(p.z), d: dd };
    }
    if (best) return { x: best.x, z: best.z, placed: false, tries: 0 };
    if (attempt === 2 && !taken.some((t) => Math.hypot(t.x - from.x, t.z - from.z) < MIN_SEPARATION)) {
      return { x: from.x, z: from.z, placed: false, tries: 0, fallback: true }; // no biome found: use the search origin
    }
  }
  return { none: true };
}

let busy = false;

async function placeStructure(dim, spec, spot, plan) {
  busy = true;
  const areaId = "dbe:structure_" + spec.key + "_" + system.currentTick;
  let area = false;
  try {
    try {
      await world.tickingAreaManager.createTickingArea(areaId, {
        dimension: dim,
        from: { x: spot.x - spec.area, y: MIN_Y, z: spot.z - spec.area },
        to: { x: spot.x + spec.area, y: MIN_Y, z: spot.z + spec.area },
      });
      area = true;
    } catch (e) {
      console.warn("[Structures] could not create ticking area for " + spec.key + ": " + e);
    }
    const center = { x: spot.x, y: 0, z: spot.z };
    for (let i = 0; i < 60 && !dim.isChunkLoaded(center); i++) await waitTicks(5);
    // y is ignored: the structure's own start height (heightmap projection) puts it on the surface
    world.structureManager.placeJigsawStructure(spec.structure, dim, center);
    spot.placed = true;
    console.log("[Structures] placed " + spec.key + " at " + spot.x + ", " + spot.z);
  } catch (e) {
    spot.tries = (spot.tries ?? 0) + 1;
    console.warn("[Structures] could not place " + spec.key + " (attempt " + spot.tries + "): " + e);
  } finally {
    try {
      savePlan(plan);
    } catch (e) {
      /* ignore */
    }
    if (area) {
      try {
        world.tickingAreaManager.removeTickingArea(areaId);
      } catch (e) {
        /* already gone */
      }
    }
    busy = false;
  }
}

function scan() {
  if (busy) return;
  const dim = world.getDimension(OVERWORLD);
  const plan = loadPlan();

  // plan one spot per scan, so the seed searches never pile up in a single tick
  const next = SPECS.find((s) => !plan.spots[s.key]);
  if (next) {
    const taken = Object.values(plan.spots).filter((s) => !s.none);
    plan.spots[next.key] = planSpot(dim, next, taken);
    savePlan(plan);
    return;
  }

  const players = dim.getPlayers();
  if (!players.length) return;
  for (const spec of SPECS) {
    const spot = plan.spots[spec.key];
    if (!spot || spot.none || spot.placed || (spot.tries ?? 0) >= MAX_TRIES) continue;
    if (players.some((p) => Math.hypot(p.location.x - spot.x, p.location.z - spot.z) < PLACE_DISTANCE)) {
      placeStructure(dim, spec, spot, plan);
      return;
    }
  }
}

function report(player) {
  const plan = loadPlan();
  player.sendMessage("§e[Structures] planned spots:");
  for (const spec of SPECS) {
    const s = plan.spots[spec.key];
    let state;
    if (!s) state = "§7not planned yet";
    else if (s.none) state = "§cno spot found";
    else if (s.placed) state = "§aplaced";
    else if ((s.tries ?? 0) >= MAX_TRIES) state = "§cgave up after " + s.tries + " attempts";
    else state = "§6waiting for a player nearby";
    const where = s && !s.none ? " §fX: " + s.x + " Z: " + s.z + (s.fallback ? " §7(biome not found)" : "") : "";
    player.sendMessage(" §b" + spec.key + where + " " + state);
  }
}

world.afterEvents.worldLoad.subscribe(() => {
  system.runInterval(() => {
    try {
      scan();
    } catch (e) {
      console.warn("[Structures] scan error: " + e);
    }
  }, SCAN_TICKS);

  system.afterEvents.scriptEventReceive.subscribe((ev) => {
    if (ev.id !== "dbe:structures") return;
    const src = ev.sourceEntity;
    if (!src || src.typeId !== "minecraft:player") return;
    report(src);
  });
});
